server {
    listen 80;
    server_name example.com;
    return 301 https://$host$request_uri;
}
server {
    listen 443 ssl;
    server_name example.com;
    ssl_certificate /etc/letsencrypt/live/example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;
    root /var/www/example;
    index index.html;
}

server {
    listen 443 ssl;
    server_name shop.example.com;
    ssl_certificate /etc/nginx/tls/shop.pem;
    ssl_certificate_key /etc/nginx/tls/shop.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384;
    ssl_prefer_server_ciphers off;
}

server {
    listen 443 ssl;
    server_name secure.internal.example;
    ssl_certificate /etc/nginx/tls/secure.pem;
    ssl_certificate_key /etc/nginx/tls/secure.key;
    ssl_protocols TLSv1.3;
    ssl_conf_command Ciphersuites TLS_AES_256_GCM_SHA384:TLS_CHACHA20_POLY1305_SHA256;
}

server {
    listen 443 ssl;
    server_name www.bank.example;
    ssl_certificate /etc/nginx/tls/bank.pem;
    ssl_certificate_key /etc/nginx/tls/bank.key;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
}

server {
    listen 443 ssl;
    server_name api.example.com;
    ssl_certificate /etc/letsencrypt/live/api.example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/api.example.com/privkey.pem;
    ssl_trusted_certificate /etc/letsencrypt/live/api.example.com/chain.pem;
    ssl_stapling on;
    ssl_stapling_verify on;
    resolver 1.1.1.1 8.8.8.8 valid=300s;
    resolver_timeout 5s;
}

http {
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 1d;
    ssl_session_tickets off;
    server {
        listen 443 ssl;
        server_name www.example.com;
        ssl_certificate /etc/nginx/tls/www.pem;
        ssl_certificate_key /etc/nginx/tls/www.key;
    }
}

server {
    listen 443 ssl;
    server_name dev.local;
    ssl_certificate /etc/nginx/certs/dev-local.crt;
    ssl_certificate_key /etc/nginx/certs/dev-local.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    root /var/www/dev;
}

server {
